import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {FileDirectoryIcon, SidebarCollapseIcon} from '@primer/octicons-react'
import {Button, IconButton, Label, Spinner, TextInput} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {clsx} from 'clsx'
import type React from 'react'
import {type RefObject, useEffect, useState} from 'react'

// eslint-disable-next-line @github-ui/github-monorepo/no-relative-references-outside-package
import {rtlProofPath} from '../../../shared-workspace-components/utilities/file-path-helpers'
import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {ReadOnlyKey, useReadOnly} from '../../hooks/use-read-only'
import type {WorkbenchRoutePayload} from '../../types/workbench-types'
import styles from './EditorHeader.module.css'

export type EditorHeaderProps = {
  viewControls?: React.ReactNode
  actions?: React.ReactNode
  settings?: React.ReactNode
  fileTreeShown: boolean
  toggleFileTree: (isExpanded?: boolean) => void
  onSaveFileName?: (newFileName: string) => void
  onTerminalClick: () => void
  initialPath: string
  path: string
  pathError?: boolean
  onPathChange?: () => void
  filenameInputRef?: RefObject<HTMLInputElement | null>
  moreOptionsButtonRef?: RefObject<HTMLButtonElement | null>
  fileDescription?: string | React.ReactNode
  loading?: boolean
}

export function EditorHeader({
  viewControls,
  actions,
  settings,
  onSaveFileName,
  onTerminalClick,
  initialPath,
  path,
  pathError,
  onPathChange,
  filenameInputRef,
  moreOptionsButtonRef,
  fileTreeShown,
  toggleFileTree,
  fileDescription,
  loading,
}: EditorHeaderProps) {
  const {isNewFilePage} = useRoutePayload<WorkbenchRoutePayload>()
  const {codespaceData} = useCodespaceContext()

  const [pathInputValue, setPathInputValue] = useState(initialPath)
  const [terminalRequested, setTerminalRequested] = useState(false)
  const [isEditing, setIsEditing] = useState(false)

  const matchesPath = new RegExp(`^${initialPath}/?$`).test(pathInputValue)
  const isInputValueValid = pathInputValue && !matchesPath
  const showFileInput = isNewFilePage || isEditing
  const hasCodespaceInfo = !!codespaceData.codespaceInfo

  const readOnly = useReadOnly(ReadOnlyKey.EDITOR)

  useEffect(() => {
    if (terminalRequested && hasCodespaceInfo) {
      onTerminalClick()
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setTerminalRequested(false)
    }
  }, [hasCodespaceInfo, onTerminalClick, terminalRequested])

  useEffect(() => {
    if (isNewFilePage) {
      filenameInputRef?.current?.focus()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <div
      className={`d-flex flex-row flex-items-center flex-justify-between gap-3 px-2 color-border-muted bgColor-default ${styles.container}`}
    >
      <div className={clsx('d-flex flex-row flex-items-center overflow-hidden', styles.leftContent)}>
        <div className={styles.treeToggleContainer}>
          <IconButton
            aria-label={fileTreeShown ? 'Collapse file tree' : 'Expand file tree'}
            className={clsx({[styles.treeToggleButton]: fileTreeShown})}
            icon={fileTreeShown ? SidebarCollapseIcon : FileDirectoryIcon}
            onClick={() => toggleFileTree()}
            variant="invisible"
          />
        </div>
        {showFileInput ? (
          <div>
            <div className="d-flex flex-row flex-items-center gap-2">
              <h1 className="sr-only">
                {isNewFilePage ? 'Creating a new file in the editor' : 'Renaming file in the editor'}
              </h1>
              <TextInput
                ref={filenameInputRef}
                placeholder="Name your file..."
                value={pathInputValue}
                onChange={e => {
                  onPathChange?.()
                  setPathInputValue(e.target.value)
                }}
              />
              <Button
                aria-disabled={!isInputValueValid}
                inactive={!isInputValueValid}
                onClick={() => isInputValueValid && onSaveFileName?.(pathInputValue)}
                variant="primary"
              >
                Save
              </Button>
              {!isNewFilePage && (
                <Button
                  onClick={() => {
                    setIsEditing?.(false)
                    onPathChange?.()
                    setPathInputValue(path)

                    // return focus to the "more options" button
                    moreOptionsButtonRef?.current?.focus()
                  }}
                >
                  Cancel
                </Button>
              )}
            </div>
            {pathError && (
              <InlineMessage className="mt-2" variant="critical">
                Filename conflicts with an existing file or directory
              </InlineMessage>
            )}
          </div>
        ) : (
          <div className="ml-2 d-flex flex-items-center gap-1">
            <h1 className={styles.fileHeading}>{rtlProofPath(path)}</h1>
            {!!fileDescription && <span className={styles.fileDescription}>{fileDescription}</span>}
            {readOnly && <Label variant="secondary">Read-only</Label>}
            {loading && <Spinner size="small" />}
          </div>
        )}
      </div>
      <div className={clsx('d-flex gap-2 mr-2 flex-items-center', styles.rightContent)}>
        {viewControls}
        {actions}
        {settings}
      </div>
    </div>
  )
}
