import type {StructuredPatch as ParsedDiff} from 'diff'
import type {TypedJSONRPCClient, TypedJSONRPCServer, TypedJSONRPCServerAndClient} from 'json-rpc-2.0'

import type {
  ClientRpcMethods,
  CommitData,
  FileEntry,
  GitFileStatuses,
  IFileSyncer,
  OurDuplex,
  ServerRpcMethods,
} from '../../types/file-syncer-v2-types'
import type {IterationMetadata} from '../../types/workbench-types'

export const RPC_TIMEOUT = 5000
export const RPC_TIMEOUT_EXTENDED = 30000

export class CodespaceFileSyncerClient implements IFileSyncer {
  isDisposed = false
  jsonRpcClient: TypedJSONRPCClient<ServerRpcMethods>
  jsonRpcServer: TypedJSONRPCServer<ClientRpcMethods>
  connection: OurDuplex

  constructor(
    jsonRpcServerAndClient: TypedJSONRPCServerAndClient<ClientRpcMethods, ServerRpcMethods>,
    connection: OurDuplex,
  ) {
    this.jsonRpcClient = jsonRpcServerAndClient.client
    this.jsonRpcServer = jsonRpcServerAndClient.server
    this.connection = connection
  }

  async openFile(path: string): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('openFile', {path})
  }

  async createDirectory(path: string): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('createDirectory', {path})
  }

  async deleteFile(path: string): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('deleteFile', {path})
  }

  async renameFile(oldPath: string, newPath: string): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('renameFile', {oldPath, newPath})
  }

  async writeFileString(path: string, content: string): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('writeFileString', {path, content})
  }

  async writeFileBytes(path: string, content: Uint8Array): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('writeFileBytes', {path, content})
  }

  async writeFileDiff(path: string, diff: ParsedDiff): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('writeFileDiff', {path, diff})
  }

  async readFileString(path: string): Promise<string> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    if (path.startsWith('src/assets/')) return ''
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('readFileString', {path})
  }

  async readFileBytes(path: string): Promise<Uint8Array> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('readFileBytes', {path})
  }

  async readFileDiff(path: string): Promise<ParsedDiff> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('readFileDiff', {path})
  }

  async getDirectoryContents(path: string): Promise<FileEntry[]> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('getDirectoryContents', {path})
  }

  async pauseFileWatchers(): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('pauseFileWatchers', {})
  }

  async resumeFileWatchers(): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('resumeFileWatchers', {})
  }

  async createCommit(message: string, sasUri: string, writeIterationHistoryToGit?: boolean): Promise<{sha: string}> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient
      .timeout(RPC_TIMEOUT_EXTENDED)
      .request('createCommit', {message, sasUri, writeIterationHistoryToGit})
  }

  async checkoutCommitish(sha: string, shouldForcePushToRemote?: boolean, branchName?: string): Promise<string> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient
      .timeout(RPC_TIMEOUT)
      .request('checkoutCommitish', {sha, shouldForcePushToRemote, branchName})
  }

  async getGitStatus(): Promise<GitFileStatuses> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('getGitStatus', {})
  }

  async getGitCatFile(sha: string, path: string): Promise<string> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('getGitCatFile', {sha, path})
  }

  async syncRepository(): Promise<boolean> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('syncRepository', {})
  }

  async buildStaticPreview(): Promise<void> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT_EXTENDED).request('buildStaticPreview', {})
  }

  async executeCommand(command: string, args: string[]): Promise<string | null> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('executeCommand', {command, args})
  }

  async getCommitHistory(maxCount?: number, skip?: number): Promise<CommitData[]> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('getCommitHistory', {maxCount, skip})
  }

  async getIterationHistory(): Promise<IterationMetadata[]> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    // Use longer timeout to accomodate users with large histories
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT_EXTENDED).request('getIterationHistory', {})
  }

  async getLastCommit(): Promise<IterationMetadata> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('getLastCommit', {})
  }

  async getChangedFilesFiltered(sha: string): Promise<GitFileStatuses> {
    if (this.isDisposed) throw new Error('FileSyncer is disposed')
    return await this.jsonRpcClient.timeout(RPC_TIMEOUT).request('getChangedFilesFiltered', {sha})
  }

  dispose(): void {
    // Clean up resources
    this.isDisposed = true
    this.jsonRpcClient.rejectAllPendingRequests('FileSyncerClient is disposed')
    this.jsonRpcServer.removeMethod('notifyFileChanged')
    this.connection.removeAllListeners('data')
    this.connection.removeAllListeners()
    this.connection.destroy()
  }
}
