import {useCallback, useState} from 'react'

interface UseImageDragDropOptions {
  /** Function to attach the image file */
  attachImageFromFile: (file: File) => Promise<void>
  /** Whether drag-and-drop/paste should be disabled */
  isDisabled?: boolean
  /** Optional callback for successful attachment */
  onSuccess?: (action: 'drop' | 'paste') => void
  /** Optional callback for failed attachment */
  onError?: (action: 'drop' | 'paste') => void
}

interface UseImageDragDropReturn {
  isDragOver: boolean
  handleDragEnter: (e: React.DragEvent<HTMLTextAreaElement>) => void
  handleDragOver: (e: React.DragEvent<HTMLTextAreaElement>) => void
  handleDragLeave: (e: React.DragEvent<HTMLTextAreaElement>) => void
  handleDrop: (e: React.DragEvent<HTMLTextAreaElement>) => Promise<void>
  handlePaste: (e: React.ClipboardEvent<HTMLTextAreaElement>) => Promise<void>
}

/**
 * Hook for handling image drag-and-drop and paste functionality in textareas.
 * Supports JPEG, PNG, and WebP image formats.
 *
 * @param options - Configuration options
 * @returns Object with drag-and-drop event handlers and drag state
 *
 * @example
 * ```tsx
 * const { isDragOver, handleDragEnter, handleDrop, handlePaste, ... } = useImageDragDrop({
 *   attachImageFromFile,
 *   isDisabled: true,
 *   onSuccess: (action) => announce(`Image ${action === 'drop' ? 'attached' : 'pasted'}`),
 *   onError: (action) => announce(`Failed to ${action} image`),
 * })
 * ```
 */
export function useImageDragDrop({
  attachImageFromFile,
  isDisabled = false,
  onSuccess,
  onError,
}: UseImageDragDropOptions): UseImageDragDropReturn {
  const [isDragOver, setIsDragOver] = useState(false)

  // Helper function to check if drag contains valid image files
  const hasValidImageType = useCallback((dataTransfer: DataTransfer): boolean => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp']

    if (dataTransfer.items) {
      return Array.from(dataTransfer.items).some(item => item.kind === 'file' && validTypes.includes(item.type))
    }

    return false
  }, [])

  const handleDragEnter = useCallback(
    (e: React.DragEvent<HTMLTextAreaElement>) => {
      e.preventDefault()
      e.stopPropagation()

      // Check if the drag contains valid image files (not general files)
      if (hasValidImageType(e.dataTransfer)) {
        setIsDragOver(true)
      }
    },
    [hasValidImageType],
  )

  const handleDragOver = useCallback((e: React.DragEvent<HTMLTextAreaElement>) => {
    e.preventDefault()
    e.stopPropagation()
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent<HTMLTextAreaElement>) => {
    e.preventDefault()
    e.stopPropagation()

    // Only set drag over to false if we're leaving the textarea itself
    // (not just a child element)
    if (e.currentTarget === e.target) {
      setIsDragOver(false)
    }
  }, [])

  const handleDrop = useCallback(
    async (e: React.DragEvent<HTMLTextAreaElement>) => {
      e.preventDefault()
      e.stopPropagation()
      setIsDragOver(false)

      // Don't process drops if disabled
      if (isDisabled) {
        return
      }

      const files = Array.from(e.dataTransfer.files)

      if (files.length === 0) {
        return
      }

      // Only process the first file
      const file = files[0]
      if (!file) {
        return
      }

      try {
        await attachImageFromFile(file)
        onSuccess?.('drop')
      } catch {
        // Error handling is done in the attachImageFromFile hook itself
        onError?.('drop')
      }
    },
    [isDisabled, attachImageFromFile, onSuccess, onError],
  )

  const handlePaste = useCallback(
    async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
      // Don't interfere if disabled
      if (isDisabled) {
        return
      }

      const items = Array.from(e.clipboardData.items)
      const imageItem = items.find(item => item.type.startsWith('image/'))

      // If no image in clipboard, allow default paste behavior (text)
      if (!imageItem) {
        return
      }

      // Prevent default paste behavior when handling image
      e.preventDefault()

      const file = imageItem.getAsFile()
      if (!file) {
        return
      }

      try {
        await attachImageFromFile(file)
        onSuccess?.('paste')
      } catch {
        // Error handling is done in the attachImageFromFile hook itself
        onError?.('paste')
      }
    },
    [isDisabled, attachImageFromFile, onSuccess, onError],
  )

  return {
    isDragOver,
    handleDragEnter,
    handleDragOver,
    handleDragLeave,
    handleDrop,
    handlePaste,
  }
}
