const MonacoEditor = lazyWithPreload(async () => ({default: (await import('./MonacoEditor')).MonacoEditor}))
const DiffEditor = lazyWithPreload(async () => ({default: (await import('@monaco-editor/react')).DiffEditor}))

// Track min editor width to auto-collapse tree
const MIN_USEFUL_EDITOR_WIDTH = 480
const ACTIVE_EDITING_TIMEOUT_MS = 500
const WRITE_FILE_DEBOUNCE_MS = 500

const viewStates = new Map<string, editorTypes.ICodeEditorViewState>()

function PlainTextStatus({children}: PropsWithChildren) {
  return <div className="d-flex flex-justify-center tmp-m-3 fgColor-muted height-full">{children}</div>
}

type EditTracking = {
  lastSeenLength: number | null
  newLength: number | null
  path: string | null
}

export type EditorProps = {
  copilotAccessAllowed?: boolean
  copilotCurrentTopic?: CopilotChatRepo
} & Pick<EditorHeaderProps, 'onTerminalClick'>

export function Editor({copilotAccessAllowed, copilotCurrentTopic, ...editorHeaderProps}: EditorProps) {
  const {beforeMount} = useMonacoEditor(true)
  const {markdownDocsUrl, monacoWorkerUrls} = useAppPayload<WorkspaceEditorAppPayload>()
  configureMonaco(monacoWorkerUrls)
  const {blobContents, large, isBinary, editorSettings, isNewFilePage, workbench} =
    useRoutePayload<WorkbenchRoutePayload>()
  const {selectedElement} = useTargetedEditsContext()
  const {
    ORIGINAL_CONTENTS_URI_PREFIX,
    editorMode,
    editorPath,
    enableLanguageFeatures,
    getLanguage,
    hasInitializedModelValue,
    originalFileContent,
    registerMonaco,
    setHasInitializedModelValue,
    setWatchingPath,
    watchingPath,
    setDiffComputed,
    diffComputed,
  } = useEditorContext()
  const {resolvedColorScheme} = useTheme()
  const {isAgentBusy} = useAgentStatus()

  const {data: vscodeOnigurumaLib, isLoading: isLoadingOnigurumaWasm, isError} = useOnigurumaWasm()
  const {
    contentStateStamp,
    fileSyncerStarted,
    getFileSyncerV2,
    notifyEdited,
    syncerMode,
    fileContentsRef,
    forceContentRefresh,
    setFileContentsRef,
  } = useFileSyncerContext()
  const {currentRefinementId} = useIterationHistory()
  const {toggleFileTree, fileTreeShown, minimapEnabled} = useWorkbenchUI()
  const readOnly = useReadOnly(ReadOnlyKey.EDITOR)
  const {fetchFromCodespaceApi} = useFetchFromCodespaceApi()

  const [pathError, setPathError] = useState(false)
  const [initialBrowserWidth, setInitialBrowserWidth] = useState<number | null>(null)
  const [value, setValue] = useState<string | undefined>(undefined)
  const [lastFetchedPath, setLastFetchedPath] = useState<string | null>(null)
  const [isStaleContent, setIsStaleContent] = useState(false)
  const [shouldDiffChanges, setShouldDiffChanges] = useState(false)
  const [isEditorNarrow, setIsEditorNarrow] = useState(false)

  const editorRef = useRef<editorTypes.IStandaloneCodeEditor | null>(null)
  const diffEditorRef = useRef<editorTypes.IStandaloneDiffEditor | null>(null)
  const editorPanelRef = useRef<HTMLDivElement | null>(null)
  const filenameInputRef = useRef<HTMLInputElement>(null)
  const moreOptionsButtonRef = useRef<HTMLButtonElement>(null)
  const previousContentStateStampRef = useRef<number | null>(null)
  const previousEditorPathRef = useRef<string | null>(null)
  const lastLspErrorTimestampRef = useRef<number>(0)
  const showingOriginalContentRef = useRef<boolean>(false)
  const blobUrlRef = useRef<string | null>(null)
  const editTrackingRef = useRef<EditTracking | null>(null)
  const fileTreeRef = useRef<HTMLDivElement | null>(null)
  const currentBlobContents = useObjectWrapper(blobContents ?? '')
  const isMarkdownFile = isMarkdown(editorPath)
  const {type: mediaType} = getMediaFileType(editorPath)
  // use refs to ensure monaco editor callbacks that are subscribed in `onMount` always have the latest data
  const currentPath = useObjectWrapper(editorPath)
  const isActivelyEditingRef = useRef(false)
  const resetActiveEditingTimeoutRef = useRef<number | null>(null)

  const isDarkTheme = resolvedColorScheme && resolvedColorScheme.includes('dark')
  const theme = isDarkTheme ? 'github-dark' : 'github-light'

  // Custom beforeMount that adds workbench-specific theme customizations
  const customBeforeMount = useCallback(
    (monaco: Monaco) => {
      // Call the original beforeMount first
      beforeMount(monaco)

      // Override line number colors for better accessibility
      // Use the active line number color for all line numbers since it's accessible
      monaco.editor.defineTheme('github-light', {
        base: 'vs',
        inherit: true,
        rules: [],
        colors: {
          'editorLineNumber.foreground': '#1f2328',
          'editorLineNumber.activeForeground': '#1f2328',
        },
      })

      monaco.editor.defineTheme('github-dark', {
        base: 'vs-dark',
        inherit: true,
        rules: [],
        colors: {
          'editorLineNumber.foreground': '#e6edf3',
          'editorLineNumber.activeForeground': '#e6edf3',
        },
      })
    },
    [beforeMount],
  )

  const preferenceToString = useCallback((pref: boolean) => (pref ? 'true' : 'false'), [])

  // const {initialTaskId, initialTaskSource} = useFocusedTask()
  const [searchParams] = useSearchParams()
  const initialPath = searchParams.get(initialPathQueryParam) || editorPath || ''

  useResizeObserver(
    () => {
      const isNarrow = (editorPanelRef.current && editorPanelRef.current.offsetWidth < MIN_USEFUL_EDITOR_WIDTH) ?? false
      if (isNarrow !== isEditorNarrow) setIsEditorNarrow(isNarrow)
    },
    editorPanelRef,
    [],
  )

  const enableLanguageFeaturesForEditorModel = useCallback(
    (editor: editorTypes.ICodeEditor, filePath: string, initialFileContent: string) => {
      const newModel = editor.getModel()
      if (newModel) {
        enableLanguageFeatures(newModel, filePath, initialFileContent)
      }
    },
    [enableLanguageFeatures],
  )

  const handlePathChange = useCallback(() => {
    setPathError(false)
  }, [])

  const checkAndCollapseFileTree = () => {
    if (isEditorNarrow && fileTreeShown) {
      toggleFileTree(false)
    }
  }

  useLayoutEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setInitialBrowserWidth(document.body.offsetWidth || 0)
  }, [])

  useEffect(() => {
    const treeElement = fileTreeRef.current
    if (!treeElement) return
    treeElement.toggleAttribute('inert', !fileTreeShown)
  }, [fileTreeShown])

  useEffect(() => {
    /**
     * Alert if clicked on outside of element
     */
    function handleClickOutside(event: MouseEvent) {
      const isOverlay = (window.innerWidth > 0 ? window.innerWidth : screen.width) <= 768
      if (isOverlay && fileTreeRef.current && !fileTreeRef.current.contains(event.target as Node)) {
        // Collapse file tree if clicked outside and not pinned
        if (fileTreeShown) {
          toggleFileTree(false)
        }
      }
    }
    // Bind the event listener
    document.addEventListener('mousedown', handleClickOutside)
    return () => {
      // Unbind the event listener on clean up
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [fileTreeShown, toggleFileTree])

  useResizeObserver(() => {
    const currentBrowserWidth = document.body.offsetWidth
    if (initialBrowserWidth !== null && currentBrowserWidth < initialBrowserWidth) {
      checkAndCollapseFileTree()
    }
    setInitialBrowserWidth(currentBrowserWidth)
  }, editorPanelRef)

  const {preference: codeLineWrapEnabled, updatePreference: setCodeLineWrapEnabled} = useUserPreference(
    'code_line_wrap_enabled',
    editorSettings.codeLineWrapEnabled,
    preferenceToString,
    true,
  )

  // TODO: update styling???
  const {preference: whitespaceHidden, updatePreference: setWhitespaceHidden} = useUserPreference(
    'workbench_whitespace_hidden',
    editorSettings.whitespaceHidden,
    preferenceToString,
  )

  const {preference: problemsHidden, updatePreference: setProblemsHidden} = useUserPreference(
    'workbench_problems_hidden',
    editorSettings.problemsHidden,
    preferenceToString,
  )

  const options: MonacoEditorProps['options'] = useMemo(
    () => ({
      ariaLabel: `Content Editor. ${escapeEditorHintAltText}`,
      minimap: {enabled: minimapEnabled},
      readOnly: readOnly || syncerMode === 'blobStorage' || !!isAgentBusy || !fileSyncerStarted,
      fixedOverflowWidgets: true,
      padding: {top: 8},
      wordWrap: codeLineWrapEnabled ? 'on' : 'off',
      'semanticHighlighting.enabled': false,
      stickyScroll: {enabled: false},
      isStaleContent,
      shouldDiffChanges,
    }),
    [
      codeLineWrapEnabled,
      fileSyncerStarted,
      isAgentBusy,
      isStaleContent,
      shouldDiffChanges,
      syncerMode,
      readOnly,
      minimapEnabled,
    ],
  )

  const diffOptions: DiffEditorProps['options'] = useMemo(
    () => ({
      ...options,
      ariaLabel: `Diff Editor. ${escapeEditorHintAltText}`,
      modifiedAriaLabel: 'Modified Content Editor',
      originalAriaLabel: 'Original Content Editor',
      readOnly: true,
      renderGutterMenu: false, // setting false to prevent AbstractContextKeyService error. see https://github.com/microsoft/monaco-editor/issues/4581
      renderSideBySide: false,
      useInlineViewWhenSpaceIsLimited: false,
    }),
    [options],
  )

  const language = useMemo(() => {
    const lang = getLanguage(editorPath)
    // Fallback to typescript if wasm does not load or is unsupported
    if (isError && lang === 'typescriptreact') {
      return 'typescript'
    }
    return lang
  }, [editorPath, getLanguage, isError])

  // Cleanup blob URLs when component unmounts or path changes
  useEffect(() => {
    return () => {
      if (blobUrlRef.current) {
        cleanupBlobUrlV2(blobUrlRef.current)
        blobUrlRef.current = null
      }
    }
  }, [editorPath])

  const updateEditTrackingForFile = useCallback((trackingPath: string, length: number | null) => {
    editTrackingRef.current = {
      lastSeenLength: length,
      newLength: length,
      path: trackingPath,
    }
  }, [])

  const updateEditTrackingWithEdit = useCallback((length: number | null) => {
    if (editTrackingRef.current) {
      editTrackingRef.current.newLength = length
    }
  }, [])

  // Fetch and process file content based on file type
  const fetchFileContent = useCallback(
    async (filePath: string): Promise<string | null> => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer) return null

      let content: string | null = null

      if (isAssetFile(filePath)) {
        // For asset files, try to fetch from the backend first
        try {
          const blob = await downloadAssetFromAgent(filePath, fetchFromCodespaceApi)
          if (blob) {
            const category = getAssetCategory(filePath)
            if (category === 'audio' || category === 'video' || category === 'document') {
              // Create blob URL for media files and PDFs for better performance and embedding support
              content = URL.createObjectURL(blob)
            } else {
              // Convert to data URL for images
              content = await new Promise<string>((resolve, reject) => {
                const reader = new FileReader()
                reader.onload = () => resolve(reader.result as string)
                reader.onerror = reject
                reader.readAsDataURL(blob)
              })
            }
          }
        } catch {
          // Fallback to regular file reading if asset fetch fails
          content = await readMediaFile(filePath, fileSyncer)
        }
      } else {
        // Use the original media-utils for regular files
        content = await readMediaFile(filePath, fileSyncer)
      }

      // Store blob URLs in ref for cleanup
      if (content && content.startsWith('blob:')) {
        // Clean up any existing blob URL first
        if (blobUrlRef.current) {
          cleanupBlobUrlV2(blobUrlRef.current)
        }
        blobUrlRef.current = content
      }

      return content
    },
    [getFileSyncerV2, fetchFromCodespaceApi],
  )

  // Load file content with proper handling for different file types
  const loadContent = useCallback(async () => {
    const fileState = fileContentsRef.current?.[editorPath]
    // Last original content during iteration (e.g. if the same file was already updated)
    const fileOriginalContent = fileState?.updatedContent || fileState?.content || ''
    setShouldDiffChanges(false) // Reset diffing

    // When agent is navigating during an iteration, display the original content on initial file load
    // Skip this for binary files (images, videos, audio, PDFs) as cached content might be wrong format
    if (
      isAgentBusy &&
      watchingPath === editorPath &&
      !showingOriginalContentRef.current &&
      mediaType !== 'image' &&
      mediaType !== 'video' &&
      mediaType !== 'audio' &&
      mediaType !== 'pdf'
    ) {
      setValue(fileOriginalContent)
      updateEditTrackingForFile(editorPath, fileOriginalContent.length)
      showingOriginalContentRef.current = true
      setIsStaleContent(true)
      setWatchingPath(null)
      forceContentRefresh()
    } else {
      // For binary files, clear any cached content to prevent format mismatches
      if (mediaType === 'image' || mediaType === 'video' || mediaType === 'audio' || mediaType === 'pdf') {
        if (fileState) {
          setFileContentsRef({
            ...fileContentsRef.current,
            [editorPath]: {
              ...fileState,
              content: undefined,
              updatedContent: undefined,
            },
          })
        }
      }

      const content = await fetchFileContent(editorPath)
      if (content !== null) {
        setValue(content)
        updateEditTrackingForFile(editorPath, content.length)

        // For asset files, mark as initialized since they don't go through Monaco model creation
        if (editorPath.startsWith('src/assets/')) {
          setHasInitializedModelValue(true)
        }
      } else {
        setValue(undefined)
        updateEditTrackingForFile(editorPath, null)
      }

      if (showingOriginalContentRef.current) {
        setShouldDiffChanges(true)
        if (content && fileState) {
          setFileContentsRef({
            ...fileContentsRef.current,
            [editorPath]: {
              ...fileState,
              updatedContent: content,
            },
          })
        }
      }
      showingOriginalContentRef.current = false
      setIsStaleContent(false)
    }
  }, [
    editorPath,
    fetchFileContent,
    fileContentsRef,
    forceContentRefresh,
    isAgentBusy,
    mediaType,
    setFileContentsRef,
    setHasInitializedModelValue,
    setWatchingPath,
    updateEditTrackingForFile,
    watchingPath,
  ])

  // Clear value when editorPath changes to prevent stale content
  useEffect(() => {
    if (previousEditorPathRef.current !== null && previousEditorPathRef.current !== editorPath) {
      setValue(undefined)
    }
    previousEditorPathRef.current = editorPath
  }, [editorPath])

  // Used to refresh content when path or external content changes
  useEffect(() => {
    if (
      fileSyncerStarted &&
      !isActivelyEditingRef.current && // Don't load content when user is actively editing
      (lastFetchedPath !== editorPath || previousContentStateStampRef.current !== contentStateStamp)
    ) {
      const runLoadContent = async () => {
        try {
          await loadContent()
        } catch {
          // Handle error silently
        } finally {
          // Set value's path and content state stamp to current even if loading failed
          // This prevents infinite loading states
          setLastFetchedPath(editorPath)
          previousContentStateStampRef.current = contentStateStamp
        }
      }
      runLoadContent()
    }
  }, [loadContent, contentStateStamp, editorPath, fileSyncerStarted, lastFetchedPath])

  const cancellableFileSync = useMemo(
    // eslint-disable-next-line react-hooks/preserve-manual-memoization
    () =>
      createCancelableFunction(async (content: string, delayMs: number, signal: AbortSignal) => {
        const fileSyncer = getFileSyncerV2()
        if (!fileSyncer) {
          return
        }

        if (signal.aborted) {
          // Noop, syncing aborted
          return
        }

        await new Promise(resolve => {
          setTimeout(() => {
            resolve(true)
          }, delayMs ?? 0)
        })

        if (signal.aborted) {
          // Noop, syncing aborted
          return
        }

        await fileSyncer.writeFileString(currentPath.current, content ?? '')
        notifyEdited()
      }),
    [currentPath, getFileSyncerV2, notifyEdited],
  )

  const writeFileDebounced = useMemo(
    () =>
      // Create a debounced version of the writeFile function for future calls
      // eslint-disable-next-line react-hooks/refs
      debounce(async (newValue: string) => {
        // eslint-disable-next-line react-hooks/purity
        const timeSinceLastLspError = Date.now() - lastLspErrorTimestampRef.current

        // Debounce the file write if time since last lsp error is less than 5 seconds
        if (timeSinceLastLspError < 5000) {
          await cancellableFileSync(newValue, 5001)
          return
        }

        await cancellableFileSync(newValue, 0)
      }, WRITE_FILE_DEBOUNCE_MS),
    [cancellableFileSync],
  )

  const sendEvent = useAnalytics()

  const sendEventForEditImmediate = useCallback(() => {
    const change =
      editTrackingRef.current?.lastSeenLength && editTrackingRef.current?.newLength
        ? editTrackingRef.current.newLength - editTrackingRef.current.lastSeenLength
        : 0

    if (change === 0) {
      return
    }

    // Now that we've recorded it, the new length is our last seen for tracking
    if (editTrackingRef.current?.newLength) {
      editTrackingRef.current.lastSeenLength = editTrackingRef.current.newLength
    }

    const telemetryProperties = {
      change_size_chars: change,
      source: 'Editor.tsx',
      iteration_id: currentRefinementId || null,
      iteration_step: 'refine',
      iteration_method: 'manual_code_edit',
      iteration_uuid: uuid(),
      user_type: 'human',
      file_path: editTrackingRef.current?.path || '',
      file_length: editTrackingRef.current?.newLength || 0,
    }
    sendEvent('change_started', {
      ...telemetryProperties,
    })
    sendEvent('change_completed', {
      ...telemetryProperties,
      time_to_iterate_ms: 0,
      success: true,
    })
  }, [currentRefinementId, sendEvent])

  // For edits as a point in time, not a process, so we pair start/complete.
  // We debounce relatively heavily because we don't need every key press.
  const sendEventForEditDebounced = useDebounce(sendEventForEditImmediate, 5_000)

  const clearActiveEditingTimeout = useCallback(() => {
    if (resetActiveEditingTimeoutRef.current) {
      clearTimeout(resetActiveEditingTimeoutRef.current)
      resetActiveEditingTimeoutRef.current = null
    }
  }, [])

  const resetActiveEditingDebounced = useCallback(() => {
    // Clear any existing timeout
    clearActiveEditingTimeout()

    // Set a new timeout to reset the flag after ACTIVE_EDITING_TIMEOUT_MS of no typing
    resetActiveEditingTimeoutRef.current = window.setTimeout(() => {
      isActivelyEditingRef.current = false
      resetActiveEditingTimeoutRef.current = null
    }, ACTIVE_EDITING_TIMEOUT_MS)
  }, [clearActiveEditingTimeout])

  const onChange = useCallback(
    async (newValue: string | undefined) => {
      if (isAgentBusy) {
        // While code is being generated, they are directly syned to the file system
        // So we don't want redundant writes
        return
      }

      isActivelyEditingRef.current = true
      setValue(newValue)
      // Reset the active editing flag after ACTIVE_EDITING_TIMEOUT_MS of no typing
      resetActiveEditingDebounced()
      writeFileDebounced(newValue ?? '')

      // Set next value to see at debounce...
      updateEditTrackingWithEdit((newValue || '').length)
      sendEventForEditDebounced()
    },
    [
      isAgentBusy,
      writeFileDebounced,
      updateEditTrackingWithEdit,
      sendEventForEditDebounced,
      resetActiveEditingDebounced,
    ],
  )

  // Reset active edits when navigating to a different file
  useEffect(() => {
    isActivelyEditingRef.current = false
    clearActiveEditingTimeout()
  }, [clearActiveEditingTimeout, editorPath])

  // Reset active edits when fetching state changes
  useEffect(() => {
    if (isAgentBusy) {
      isActivelyEditingRef.current = false
      clearActiveEditingTimeout()
    }
  }, [clearActiveEditingTimeout, isAgentBusy])

  // Cleanup timeout on component unmount
  useEffect(() => {
    return () => clearActiveEditingTimeout()
  }, [clearActiveEditingTimeout])

  const registerLanguageFeatures = useCallback(
    // eslint-disable-next-line react-hooks/preserve-manual-memoization
    (editor: editorTypes.IStandaloneCodeEditor) => {
      if (currentPath.current) {
        enableLanguageFeaturesForEditorModel(editor, currentPath.current, currentBlobContents.current)
      }
    },
    [currentBlobContents, currentPath, enableLanguageFeaturesForEditorModel],
  )

  const onMonacoValidate = useCallback((monaco: Monaco, uri: Uri, markers: editorTypes.IMarker[]) => {
    let hasErrors = false

    const errorMarkers: SparkError[] = []

    for (const m of markers) {
      const common = {
        source: 'editor' as const,
        messageRaw: m.message,
        messagePretty: m.message,
        path: m.resource?.path,
        line: m.startLineNumber,
        column: m.startColumn,
      }

      if (m.severity >= monaco.MarkerSeverity.Error) {
        errorMarkers.push({...common})
      }
    }

    if (errorMarkers.length !== 0) {
      hasErrors = true
    }

    if (hasErrors) {
      if (lastLspErrorTimestampRef.current === 0) {
        lastLspErrorTimestampRef.current = Date.now()
      }
    } else {
      lastLspErrorTimestampRef.current = 0
    }
  }, [])

  const onMonacoMount = useCallback(
    async (editor: editorTypes.IStandaloneCodeEditor, monaco: Monaco) => {
      // Workaround since monaco does not support JSX syntax highlighting
      if (vscodeOnigurumaLib) {
        // Create a registry that can create a grammar from a scope name.
        const registry = new Registry({
          onigLib: Promise.resolve(vscodeOnigurumaLib),
          loadGrammar: async scopeName => {
            // From https://github.com/microsoft/TypeScript-TmLanguage/blob/master/TypeScriptReact.tmLanguage
            // or from https://github.com/microsoft/vscode-textmate/blob/main/test-cases/themes/syntaxes/TypeScriptReact.tmLanguage.json
            if (scopeName === 'source.tsx') {
              return parseRawGrammar(JSON.stringify(TypeScriptReactTMLanguage), 'TypeScriptReact.tmLanguage.json')
            }
            // Unknown scope name
            return null
          },
        })

        // Map of monaco "language id's" to TextMate scopeNames
        const grammars = new Map()
        grammars.set('typescriptreact', 'source.tsx')
        monaco.languages.register({id: 'typescriptreact'})
        await wireTmGrammars(monaco, registry, grammars, editor)
      }
      editorRef.current = editor

      const telemetryCommandId = editor.addCommand(-1, (...args) => {
        // When user interacts with LSP (both standard and copilot), Monaco calls this command with the telemetry data
        if (args.length > 0 && args[0]) {
          const eventData = args[1]

          // Send change_completed event when LSP interaction completes (existing behavior)
          if (eventData.event_type === 'completed' || eventData.phase === 'complete' || !eventData.event_type) {
            // Common telemetry properties for both events
            const telemetryProperties = {
              user_type: 'lsp suggestion',
              file_path: eventData.file_uri,
              language: eventData.language,
              change_size_chars: eventData.change_size_chars,
              type: eventData.type,
            }

            sendEvent('change_started', {
              ...telemetryProperties,
            })
            sendEvent('change_completed', {
              ...telemetryProperties,
              time_to_iterate_ms: 0,
              success: true,
            })
          }
        }
      })
      registerMonaco(monaco, telemetryCommandId || '')

      editor.onDidChangeModel(() => {
        registerLanguageFeatures(editor)

        // Send any pending edit events for the prior file
        sendEventForEditImmediate()

        const newPath = editor.getModel()?.uri.path?.replace(/^\//, '')
        if (newPath) {
          const savedViewState = viewStates.get(newPath)
          if (savedViewState) {
            // Content was restored from cache
            const cachedContent = editor.getValue()
            setLastFetchedPath(newPath)
            setValue(cachedContent)
            updateEditTrackingForFile(newPath, cachedContent.length)
          }
        }
      })

      registerLanguageFeatures(editor)
    },
    [
      registerLanguageFeatures,
      registerMonaco,
      sendEvent,
      sendEventForEditImmediate,
      updateEditTrackingForFile,
      vscodeOnigurumaLib,
    ],
  )

  const updateMonacoDiffEditors = useCallback(() => {
    if (!diffEditorRef.current) return
    const modifiedModel = diffEditorRef.current.getModifiedEditor().getModel()
    const originalModel = diffEditorRef.current.getOriginalEditor().getModel()
    if (!modifiedModel || !originalModel) return

    originalModel.setValue(originalFileContent || '')
    diffEditorRef.current.setModel({
      original: originalModel,
      modified: modifiedModel,
    })
    setHasInitializedModelValue(true)
    diffEditorRef.current.revealFirstDiff()
  }, [originalFileContent, setHasInitializedModelValue])

  const onMonacoDiffEditorMount = useCallback(
    (diffEditor: editorTypes.IStandaloneDiffEditor, monaco: Monaco) => {
      diffEditorRef.current = diffEditor
      const modifiedEditor = diffEditor.getModifiedEditor()
      diffEditor.onDidUpdateDiff(() => {
        setDiffComputed(true)
      })

      /*
       * Workaround for bug with `DiffEditor` component and setting original/modified paths.
       * Without this, the visual diff shown by the editor doesn't update correctly when switching between files.
       * This forces the editor to update the diff view whenever the model changes.
       */
      modifiedEditor.onDidChangeModel(() => {
        updateMonacoDiffEditors()
      })
      updateMonacoDiffEditors()

      onMonacoMount(modifiedEditor, monaco)
    },
    [onMonacoMount, setDiffComputed, updateMonacoDiffEditors],
  )

  /**
   * Highlight the selected code when user in targeted edits mode
   */
  useEffect(() => {
    if (!editorRef.current || !selectedElement) return

    const {start, end} = selectedElement.location ?? selectedElement.component.location!

    editorRef.current.setSelection({
      selectionStartColumn: start.column,
      selectionStartLineNumber: start.line,
      positionColumn: end.column,
      positionLineNumber: end.line,
    })

    // Scroll to the selection
    editorRef.current.revealLineInCenter(start.line)
  }, [selectedElement])

  const editorHeader = (
    <EditorHeader
      key={`header-${editorPath}`}
      filenameInputRef={filenameInputRef}
      moreOptionsButtonRef={moreOptionsButtonRef}
      fileTreeShown={fileTreeShown}
      toggleFileTree={toggleFileTree}
      settings={
        <EditorHeaderSettings
          onCopyFileContents={useCallback(async () => await copyText(value || ''), [value])}
          codeLineWrapEnabled={!!codeLineWrapEnabled}
          whitespaceHidden={!!whitespaceHidden}
          problemsHidden={!!problemsHidden}
          setCodeLineWrapEnabled={setCodeLineWrapEnabled}
          setWhitespaceHidden={setWhitespaceHidden}
          setProblemsHidden={setProblemsHidden}
        />
      }
      initialPath={initialPath}
      path={editorPath}
      pathError={pathError}
      onPathChange={handlePathChange}
      fileDescription={
        editorMode === 'diff-editor' && !isAgentBusy ? (
          <>
            {'(previous)'}
            <ArrowBothIcon />
            {editorPath}
          </>
        ) : undefined
      }
      loading={editorMode === 'diff-editor' && !diffComputed}
      {...editorHeaderProps}
    />
  )

  // If the file is new, we don't show the editor since it complicates monaco model management,
  // and LSP features won't work.
  // Instead, we just show the header and let the user save the file then begin composing.
  if (isNewFilePage) return editorHeader

  const isFetchingValue = lastFetchedPath !== editorPath
  const isLoadingEditor = (syncerMode === 'codespace' && !fileSyncerStarted) || isLoadingOnigurumaWasm
  const isLoadingDiffOriginalContent = editorMode === 'diff-editor' && originalFileContent === null
  // For media files (assets), we don't need to wait for Monaco model initialization
  const isAssetPath = editorPath.startsWith('src/assets/')
  const isLoadingFile = isFetchingValue || (!isAssetPath && !hasInitializedModelValue) || isLoadingDiffOriginalContent

  // For assets, also check if content is still being loaded to prevent flashing
  const isAssetStillLoading = isAssetPath && isFetchingValue
  return (
    <>
      <div className={styles.editorContainer} ref={editorPanelRef}>
        <div
          aria-hidden={!fileTreeShown}
          className={clsx(styles.files, {[styles.filesShown]: fileTreeShown})}
          ref={fileTreeRef}
        >
          <div className="d-flex d-md-none flex-justify-end flex-items-center p-2">
            <IconButton
              icon={XIcon}
              variant="invisible"
              aria-label={'Hide file tree'}
              onClick={() => {
                toggleFileTree(false)
              }}
            />
          </div>
          <div className="flex-1 py-2 tmp-px-3 overflow-y-auto">
            <SimpleFileTree workbenchId={workbench.id} />
          </div>
        </div>
        <div className={clsx(styles.editorFileFrame, {[styles.fileTreeExpanded]: fileTreeShown})}>
          {editorHeader}
          {isLoadingFile && <EditorLoadingSkeleton fadeIn />}
          {editorMode === 'diff-editor' && originalFileContent !== null ? (
            <div className={clsx(styles.editorFileContainer, isLoadingFile && styles.hideEditorFile)}>
              {isLoadingEditor ? (
                <EditorLoadingSkeleton />
              ) : (
                <Suspense fallback={<EditorLoadingSkeleton fadeIn />}>
                  <DiffEditor
                    className={problemsHidden ? styles.hideProblems : undefined}
                    height="100%"
                    beforeMount={customBeforeMount}
                    language={language}
                    loading={<EditorLoadingSkeleton />}
                    theme={theme}
                    onMount={onMonacoDiffEditorMount}
                    options={diffOptions}
                    originalModelPath={`${ORIGINAL_CONTENTS_URI_PREFIX}-${editorPath}`}
                    modifiedModelPath={editorPath}
                    original={originalFileContent}
                    modified={value}
                  />
                </Suspense>
              )}
            </div>
          ) : (
            <div className={clsx(styles.editorFileContainer, isLoadingFile && styles.hideEditorFile)}>
              {large ? (
                <PlainTextStatus>
                  <p>Sorry about that, but we cannot show files that are this big right now.</p>
                </PlainTextStatus>
              ) : editorPath.startsWith('src/assets/') ? (
                value && !isAssetStillLoading ? (
                  /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
                  <MediaPreview src={value} filePath={editorPath} alt="Asset Preview" />
                ) : (
                  <EditorLoadingSkeleton fadeIn />
                )
              ) : isBinary ? (
                <PlainTextStatus>Binary file not shown.</PlainTextStatus>
              ) : isLoadingEditor ? (
                <EditorLoadingSkeleton />
              ) : (
                <Suspense fallback={<EditorLoadingSkeleton fadeIn />}>
                  <MonacoEditor
                    className={problemsHidden ? styles.hideProblems : undefined}
                    height="100%"
                    onChange={onChange}
                    path={editorPath}
                    beforeMount={customBeforeMount}
                    defaultLanguage={language || 'javascript'}
                    language={language}
                    loading={<EditorLoadingSkeleton />}
                    onMount={onMonacoMount}
                    onValidate={onMonacoValidate}
                    options={options}
                    theme={theme}
                    value={value}
                    viewStates={viewStates}
                  />
                </Suspense>
              )}
            </div>
          )}
        </div>
      </div>
      <EscapeEditorHint />
      {isMarkdownFile && <MarkdownIndicator markdownDocsUrl={markdownDocsUrl} />}
    </>
  )
}
