/**
 * Constructs the deployment URL for a workbench. Key components are:
 * - `friendlyName`: The friendly name of the workbench.
 * - `deployLogin`: The login of the user who deployed the workbench. Note in some cases this is 'mangled' to resolve illegal url characters.
 * - `domainBase`: The base domain for the deployment, typically the ACA deployment domain.
 */
export function workbenchDeployUrl({
  friendlyName,
  deployLogin,
  domainBase,
}: {
  friendlyName: string
  deployLogin: string
  domainBase: string
}) {
  return `https://${friendlyName}--${deployLogin}.${domainBase}`
}
