import {
  type FeedbackRef,
  frownIcon,
  frustratedIcon,
  grinIcon,
  type RatingOption,
  smileIcon,
  UserFeedback,
} from '@github-ui/user-feedback'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useCallback, useRef} from 'react'

type FeedbackRating = 'VERY_NEGATIVE' | 'NEGATIVE' | 'POSITIVE' | 'VERY_POSITIVE'

const feedbackRatingOptions: Array<RatingOption<FeedbackRating>> = [
  {
    name: 'Hate it',
    value: 'VERY_NEGATIVE',
    icon: frustratedIcon,
    color: 'veryDissatisfied',
  },
  {
    name: 'Not great',
    value: 'NEGATIVE',
    icon: frownIcon,
    color: 'dissatisfied',
  },
  {
    name: "It's ok",
    value: 'POSITIVE',
    icon: smileIcon,
    color: 'satisfied',
  },
  {
    name: 'Love it',
    value: 'VERY_POSITIVE',
    icon: grinIcon,
    color: 'verySatisfied',
  },
]

interface FeedbackDialogProps {
  feedbackDialogRef: React.RefObject<FeedbackRef<FeedbackRating> | null>
  initialRatingRef: React.RefObject<FeedbackRating | undefined>
  source: string
  returnFocusRef?: React.RefObject<HTMLElement | null>
  onClose?: (reason: 'submit' | 'cancel' | 'dismiss') => void
  onSubmitted?: (rating: FeedbackRating) => void
}

function FeedbackDialog({
  feedbackDialogRef,
  initialRatingRef,
  source,
  returnFocusRef,
  onClose,
  onSubmitted,
}: FeedbackDialogProps) {
  const onSubmit = useCallback(
    async (rating: FeedbackRating | null, text: string): Promise<string[]> => {
      const errors = []

      if (rating == null) {
        errors.push('Please select a rating.')
      }

      const limit = 2000
      if (text.length > limit) {
        errors.push(`Please keep your feedback within ${limit} characters or less.`)
      }

      if (errors.length > 0) {
        return errors
      }

      const body = {
        subject: `spark:workbench_id=${source}`,
        rating,
        content: text,
        hostname: window.location.hostname,
        path: window.location.pathname,
        mode: 'workbench',
      }

      try {
        const response = await verifiedFetchJSON('/github-copilot/feedback', {method: 'POST', body})
        if (!response.ok) {
          errors.push('An error occurred while submitting your feedback.')
        } else if (rating != null) {
          // Notify that feedback was successfully submitted
          onSubmitted?.(rating)
        }
      } catch {
        errors.push('An error occurred while submitting your feedback.')
      }

      return errors
    },
    [source, onSubmitted],
  )

  const onFeedbackClose = useCallback(
    (reason: 'submit' | 'cancel' | 'dismiss') => {
      if (reason === 'dismiss' && initialRatingRef.current) {
        // User dismissed via X or Escape - auto-submit with initial rating if available
        void onSubmit(initialRatingRef.current, '')
      }
      onClose?.(reason)
    },
    [initialRatingRef, onSubmit, onClose],
  )

  return (
    <UserFeedback
      ref={feedbackDialogRef}
      options={feedbackRatingOptions}
      onSubmit={onSubmit}
      onClose={onFeedbackClose}
      returnFocusRef={returnFocusRef}
    />
  )
}

export function useFeedbackDialog(source: string) {
  const feedbackDialogRef = useRef<FeedbackRef<FeedbackRating>>(null)
  const initialRatingRef = useRef<FeedbackRating | undefined>(undefined)

  const openFeedback = useCallback((initialRatingValue?: FeedbackRating) => {
    initialRatingRef.current = initialRatingValue
    feedbackDialogRef.current?.openDialog(initialRatingValue)
  }, [])

  const DialogComponent = useCallback(
    (props: Pick<FeedbackDialogProps, 'onClose' | 'onSubmitted' | 'returnFocusRef'>) => (
      <FeedbackDialog
        feedbackDialogRef={feedbackDialogRef}
        initialRatingRef={initialRatingRef}
        source={source}
        {...props}
      />
    ),
    [source],
  )

  return {
    openFeedback,
    FeedbackDialog: DialogComponent,
  }
}
