import {useLocation} from '@github-ui/react-router'
import {FileIcon} from '@primer/octicons-react'
import {TreeView} from '@primer/react'
import {SkeletonAvatar, SkeletonText} from '@primer/react/experimental'
import {useMemo} from 'react'

import {useFilesContext} from '../contexts/FilesContext'
import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import {useWorkbenchNavigate} from '../hooks/use-workbench-navigate'
import {buildFileTree} from '../utilities/files'
import styles from './SimpleFileTree.module.css'

const DEFAULT_SKELETON_ROW_COUNT = 3

function FileTreeLoadingSkeleton({rowCount = DEFAULT_SKELETON_ROW_COUNT}: {rowCount?: number}) {
  const lines = Array.from({length: rowCount}, (_, index) => index + 1)
  return (
    <ul className={styles.container} aria-label="Loading file tree">
      {lines.map(index => (
        <li key={index} className={styles.line}>
          <SkeletonAvatar square size={16} className={styles.square} />
          <SkeletonAvatar square size={16} className={styles.square} />
          <SkeletonText lines={1} />
        </li>
      ))}
    </ul>
  )
}

function SubTree(props: {base: string; items: Record<string, unknown>; workbenchId: string}) {
  const {base, items, workbenchId} = props

  // Group directories before files
  const grouped = Object.groupBy(Object.entries(items), ([_, kids]) => {
    return kids !== null ? 'dirs' : 'files'
  })

  const directories = (grouped.dirs || [])
    .sort(([lpath, _l], [rpath, _r]) => lpath.localeCompare(rpath))
    .map(([path, kids]) => {
      return (
        <DirectoryTreeViewItem
          key={base + path}
          base={base}
          path={path}
          items={kids as Record<string, unknown>}
          workbenchId={workbenchId}
        />
      )
    })

  const files = (grouped.files || [])
    .sort(([lpath, _l], [rpath, _r]) => lpath.localeCompare(rpath))
    .map(([path, _]) => {
      return <FileTreeViewItem key={base + path} base={base} path={path} workbenchId={workbenchId} />
    })

  return (
    <>
      {directories}
      {files}
    </>
  )
}

function FileTreeViewItem(props: {base: string; path: string; workbenchId: string}) {
  const {base, path, workbenchId} = props

  const location = useLocation()
  const navigate = useWorkbenchNavigate()
  const {sparkFileUrl} = useWorkbenchContext()

  const id = `${base}/${path}`

  const url = sparkFileUrl({sparkId: workbenchId, path: id.replace(/^\//, '')})

  const isSelected = location.pathname === url

  return (
    <TreeView.Item
      id={id}
      key={id}
      current={isSelected}
      onSelect={() => {
        navigate(id.replace(/^\//, ''))
      }}
    >
      <TreeView.LeadingVisual>
        <FileIcon />
      </TreeView.LeadingVisual>
      {path}
    </TreeView.Item>
  )
}

function DirectoryTreeViewItem(props: {
  base: string
  path: string
  items: Record<string, unknown>
  workbenchId: string
}) {
  const {base, path, items, workbenchId} = props
  const id = `${base}/${path}`
  return (
    <TreeView.Item id={id} key={id} defaultExpanded>
      <TreeView.LeadingVisual>
        <TreeView.DirectoryIcon />
      </TreeView.LeadingVisual>
      {path}
      <TreeView.SubTree>
        <SubTree base={id} items={items} workbenchId={workbenchId} />
      </TreeView.SubTree>
    </TreeView.Item>
  )
}

interface FileTreeProps {
  workbenchId: string
}

export function SimpleFileTree({workbenchId}: FileTreeProps) {
  // V2 stuff
  const {getFileList} = useFilesContext()
  const fileList = getFileList()

  const fileTree = useMemo(() => {
    const files = fileList.map(file => file.path)
    return buildFileTree(files)
  }, [fileList])

  if (fileList.length === 0) {
    return <FileTreeLoadingSkeleton />
  }

  return (
    <TreeView aria-label="File tree">
      <SubTree base="" items={fileTree} workbenchId={workbenchId} />
    </TreeView>
  )
}
