interface VideoPreviewProps {
  src: string
  className?: string
  onError?: (error: Error) => void
}

export function VideoPreview({src, className, onError}: VideoPreviewProps) {
  const handleError = (_e: React.SyntheticEvent<HTMLVideoElement>) => {
    const error = new Error('Video loading failed')
    if (onError) {
      onError(error)
    }
  }

  if (!src || (!src.startsWith('blob:') && !src.startsWith('data:video/'))) {
    return (
      <div className="d-flex flex-column flex-justify-center flex-items-center height-full tmp-p-4">
        <p>Error loading video file. The file may be corrupted or not a valid video format.</p>
      </div>
    )
  }

  return (
    <div className="d-flex flex-justify-center flex-items-center height-full tmp-p-4">
      {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
      <video controls src={src} className={`width-full ${className || ''}`} onError={handleError}>
        Your browser does not support the video element.
      </video>
    </div>
  )
}
