import {LogIcon, SparkleFillIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {clsx} from 'clsx'

import {useErrors} from '../../contexts/ErrorsContext'
import {useAgentStatus} from '../../contexts/WorkbenchStoreContext'
import {useWorkbench} from '../../hooks/use-workbench'
import {fixAllPrompt} from '../../utilities/error'
import {ErrorDisplay} from '../ErrorDisplay'
import styles from './ErrorOverlay.module.css'

export function ErrorOverlay() {
  const {overlayErrors} = useErrors()
  const {submitPrompt} = useWorkbench()
  const {isAgentBusy} = useAgentStatus()

  const firstError = overlayErrors[0]
  const isVisible = !isAgentBusy && overlayErrors.length > 0

  return (
    <div className={isVisible ? clsx(styles.motion, styles.motionVisible) : clsx(styles.motion)}>
      <div className={styles.errorContent}>
        <Blankslate>
          <Blankslate.Visual>
            <LogIcon size={32} />
          </Blankslate.Visual>
          <Blankslate.Heading>
            <span className={styles.label}>Hm, something went wrong</span>
          </Blankslate.Heading>
          {firstError && (
            <>
              <Blankslate.Description>
                <ErrorDisplay error={firstError} showSource />
              </Blankslate.Description>
              {submitPrompt && (
                <Button
                  variant="primary"
                  leadingVisual={SparkleFillIcon}
                  onClick={() => {
                    submitPrompt(fixAllPrompt, 'refine', 'attachments', {
                      attachments: {
                        errors: [{message: firstError.messageRaw}],
                      },
                    })
                  }}
                  disabled={isAgentBusy}
                  inactive={isAgentBusy}
                  className="tmp-mt-3"
                >
                  Autofix error
                </Button>
              )}
            </>
          )}
        </Blankslate>
      </div>
    </div>
  )
}
