import {getLanguage, LspServerType} from '@github/codespaces-lsp'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useNavigate} from '@github-ui/use-navigate'
import {type PropsWithChildren, useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {DEFAULT_FILE_PATH} from '../../constants'
import {enableLanguageFeatures, ORIGINAL_CONTENTS_URI_PREFIX} from '../../lsp/monaco-lsp-connector'
import {useLsps} from '../../lsp/use-lsps'
import usePrevious from '../../monaco/use-previous'
import {useAnalytics} from '../../telemetry/use-analytics'
import type {WorkbenchRoutePayload} from '../../types/workbench-types'
import {useCodespaceContext} from '../CodespaceContext'
import {useFilesContext} from '../FilesContext'
import {useFileSyncerContext} from '../FileSyncerContext'
import {sparkFilePathRegex, useWorkbenchContext} from '../WorkbenchContext'
import {useAgentStatus} from '../WorkbenchStoreContext'
import {EditorContext, type EditorMode} from './index'

const FILE_NAVIGATION_DELAY = 5000 // 5 seconds delay

function currentFilePath() {
  const pathname = window.location.pathname.replace(sparkFilePathRegex, '')
  return decodeURIComponent(pathname)
}

export function EditorContextProvider({children}: PropsWithChildren) {
  const {path: routePath, workbench} = useRoutePayload<WorkbenchRoutePayload>()
  const {fileChangeStack, setFileChangeStack, forceContentRefresh} = useFileSyncerContext()
  const {getFileList} = useFilesContext()
  const {sparkFileUrl} = useWorkbenchContext()
  const {isAgentBusy} = useAgentStatus()
  const navigate = useNavigate()
  const sendEvent = useAnalytics()
  const {codespaceData} = useCodespaceContext()
  const {registerMonaco} = useLsps(codespaceData, sendEvent, codespaceData.remoteProvider, [LspServerType.Typescript])
  const previousIsAgentBusy = usePrevious(isAgentBusy)
  const previousRoutePath = usePrevious(routePath)
  const lastNavigationTimeRef = useRef<number>(0)

  const [hasInitializedModelValue, setHasInitializedModelValue] = useState(false)
  const [isAnimating, setIsAnimating] = useState(false)
  const [editorPath, setEditorPath] = useState<string>(routePath || DEFAULT_FILE_PATH)
  const [watchingPath, setWatchingPath] = useState<string | null>(null)
  const [originalFileContent, setOriginalFileContent] = useState<string | null>(null)
  const [editorMode, setEditorMode] = useState<EditorMode>('editor')
  const [diffComputed, setDiffComputed] = useState<boolean>(false)

  const previousEditorPath = usePrevious(editorPath)

  /**
   * Handles file updates from "notifyFileChanged" events between fetching states
   */
  const handleFileChanges = useCallback(() => {
    // If we just finished fetching, reset the file change stack and show editor mode
    if (previousIsAgentBusy && !isAgentBusy) {
      setFileChangeStack([])
      setEditorMode('editor')
      return
    }

    // If we're not fetching, check if current file needs refresh
    if (!isAgentBusy) {
      const currentPath = currentFilePath()
      const needsRefresh = fileChangeStack.some(change => change.path === currentPath)

      if (needsRefresh) {
        forceContentRefresh()
      }

      if (fileChangeStack.length > 0) {
        setFileChangeStack([])
      }
    }
  }, [isAgentBusy, previousIsAgentBusy, fileChangeStack, setFileChangeStack, forceContentRefresh])

  // Determine if enough time has passed since last navigation
  const shouldDelayNavigation = useCallback(() => {
    const currentTime = Date.now()
    const timeElapsed = currentTime - lastNavigationTimeRef.current
    const shouldDelay = timeElapsed < FILE_NAVIGATION_DELAY && lastNavigationTimeRef.current !== 0

    return {
      shouldDelay,
      remainingTime: shouldDelay ? FILE_NAVIGATION_DELAY - timeElapsed : 0,
    }
  }, [])

  /**
   * Navigates to the next changed file that needs attention
   */
  const navigateToNextFileChange = useCallback(() => {
    if (!isAgentBusy) return

    // Only watch added/modified changes that exist in the file directory
    const fileList = getFileList()
    const nextFileChangeIndex = fileChangeStack.findIndex(
      change =>
        change.changeType === 'added' ||
        (change.changeType === 'modified' && fileList.find(file => file.path === change.path)),
    )
    const nextFileChange = fileChangeStack[nextFileChangeIndex]
    if (!nextFileChange) return

    // Handle animation delays
    if (isAnimating) {
      // eslint-disable-next-line react-hooks/immutability
      const timeoutId = window.setTimeout(navigateToNextFileChange, FILE_NAVIGATION_DELAY)
      return () => clearTimeout(timeoutId)
    }

    // Handle minimum time between navigations
    const {shouldDelay, remainingTime} = shouldDelayNavigation()
    if (shouldDelay) {
      const timeoutId = window.setTimeout(navigateToNextFileChange, remainingTime)
      return () => clearTimeout(timeoutId)
    }

    setFileChangeStack(prev => prev.slice(nextFileChangeIndex + 1))
    setEditorMode('editor')

    const nextPath = nextFileChange.path

    // Handle case when file is already open
    if (currentFilePath() === nextPath) {
      setWatchingPath(nextPath)
      forceContentRefresh()
      return
    }

    navigate(sparkFileUrl({sparkId: workbench.id, path: nextPath}))
    setEditorPath(nextPath)
    setWatchingPath(nextPath)
  }, [
    isAgentBusy,
    getFileList,
    fileChangeStack,
    isAnimating,
    shouldDelayNavigation,
    setFileChangeStack,
    navigate,
    sparkFileUrl,
    workbench.id,
    forceContentRefresh,
  ])

  useEffect(() => {
    // Track navigation
    if (editorPath !== previousEditorPath) {
      lastNavigationTimeRef.current = Date.now()
    }
  }, [editorPath, previousEditorPath])

  useEffect(() => {
    // Capture navigation that is not triggered by use-workbench-navigate (i.e. / -> open code view)
    if (previousRoutePath !== null && routePath !== previousRoutePath) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setEditorPath(routePath)
    }
  }, [routePath, previousRoutePath, editorPath])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    handleFileChanges()
  }, [handleFileChanges, fileChangeStack, isAgentBusy, previousIsAgentBusy])

  useEffect(() => {
    return navigateToNextFileChange()
  }, [navigateToNextFileChange, isAgentBusy, fileChangeStack])

  const value = useMemo(
    () => ({
      ORIGINAL_CONTENTS_URI_PREFIX,
      diffComputed,
      editorMode,
      editorPath,
      enableLanguageFeatures,
      getLanguage,
      hasInitializedModelValue,
      isAnimating,
      originalFileContent,
      registerMonaco,
      setDiffComputed,
      setEditorMode,
      setEditorPath,
      setHasInitializedModelValue,
      setIsAnimating,
      setOriginalFileContent,
      setWatchingPath,
      watchingPath,
    }),
    [
      diffComputed,
      editorMode,
      editorPath,
      hasInitializedModelValue,
      isAnimating,
      originalFileContent,
      registerMonaco,
      watchingPath,
    ],
  )

  return <EditorContext value={value}>{children}</EditorContext>
}
