import {settings} from '../../settings'
import {
  getIndexedGradient,
  type GradientStop,
  rgbToHex,
  sampleGradient,
  sampleOpacityGradient,
} from '../../utils/gradient-utils'

interface RGB {
  r: number
  g: number
  b: number
}

interface Velocity {
  x: number
  y: number
  width: number
  height: number
  rot: number
}

export class Canvas2DParticle {
  x = 0
  y = 0
  _x = Math.random() * 1.02 - 0.01
  _y = 1.02 + 0.1 * Math.random()
  rotation = Math.random() * Math.PI * 2
  depth = Math.random() * 0.9 + 0.1
  velocity: Velocity = {x: 0, y: 0, width: 0, height: 0, rot: 0}
  vx = 0
  vy = 0
  mass = 1.0
  lifeRatio = Math.random()
  life = Math.random()
  index: number
  scaleRandom = Math.random()
  _bloomIntensity = 0
  bloomIntensity = 0
  startTime = performance.now() / 1000 + Math.random() * 2
  _opacity: number
  gradient: GradientStop[]
  color: string
  initialRGB: RGB
  white: RGB = {r: 1, g: 1, b: 1}
  opacity = sampleOpacityGradient(settings.visual.opacityGradient, 0)
  scale = 0

  constructor(index: number) {
    this.index = index

    this.startTime = performance.now() / 1000 + Math.random() * 2
    this.velocity.x = Math.sign(Math.random() - 0.5) * this.depth * 0.25 // Small horizontal velocity
    this.velocity.y = this.depth * 0.5 + 0.5 // Small vertical velocity
    this.velocity.rot = Math.random() * 2 - 1 // Small rotation velocity
    this._opacity = this.depth * 0.7 + 0.3

    // Gradient selection - randomly pick one of the three gradients
    this.gradient = getIndexedGradient(settings.visual.gradients, this.index)
    // Start with initial color from gradient
    const initialRGB = sampleGradient(this.gradient, 0)
    this.color = rgbToHex(initialRGB)
    this.initialRGB = initialRGB
    this.white = {
      r: 1,
      g: 1,
      b: 1,
    }

    // Start with initial opacity from opacity gradient
    this.opacity = sampleOpacityGradient(settings.visual.opacityGradient, 0)
  }

  applyForce(fx: number, fy: number) {
    this.vx += fx / this.mass
    this.vy += fy / this.mass

    const bloom = Math.sqrt(this.vx * this.vx + this.vy * this.vy)

    if (bloom > this.bloomIntensity) {
      this.bloomIntensity = bloom
    }
  }

  updateColor(lifeRatio: number) {
    const currentRGB = sampleGradient(this.gradient, lifeRatio)

    const scale = 40
    const power = Math.max(0.1, 1.0 - this.bloomIntensity * scale)

    currentRGB.r = Math.pow(currentRGB.r, power)
    currentRGB.g = Math.pow(currentRGB.g, power)
    currentRGB.b = Math.pow(currentRGB.b, power)

    currentRGB.r = Math.min(1, currentRGB.r)
    currentRGB.g = Math.min(1, currentRGB.g)
    currentRGB.b = Math.min(1, currentRGB.b)

    this.color = rgbToHex(currentRGB)
  }

  update(delta: number, time: number, mode: string) {
    this.rotation += delta * 1.0 * this.velocity.rot // Rotate based on the time delta

    if (this.startTime < time) {
      this.life += delta * 0.2 * this.velocity.y
    }

    this.bloomIntensity *= 0.98

    this.vx *= 0.98
    this.vy *= 0.98

    this._y -= delta * 0.1 * this.velocity.y
    this._y += this.vy * this.depth
    this.y = this._y

    this._x += this.vx * this.depth
    this.x = this._x + Math.cos(delta * 0.2 + this.life) * this.velocity.x

    const lifeRatio = this.life

    // Update RGB components (0-255) as particle evolves
    // this.r = Math.round(currentRGB.r * 255);
    // this.g = Math.round(currentRGB.g * 255);
    // this.b = Math.round(currentRGB.b * 255);

    const opacity = this._opacity * sampleOpacityGradient(settings.visual.opacityGradient, lifeRatio)

    const randomScale = Math.sin(time * 5.0 + this.scaleRandom * 2 * Math.PI) * 0.5 + 0.5

    this.scale = opacity * 1.7 * (randomScale * 0.5 + 0.5)
    this.opacity = mode === 'light' ? opacity * 0.5 + 0.5 : opacity

    this.updateColor(lifeRatio)

    if (this.life > 1) {
      // Smooth respawn transition
      this.life = 0
      this._x = Math.random() * 1.02 - 0.01
      this._y = 1.02 + 0.1 * Math.random()
      this.y = this._y
      this.x = this._x
      this.vy = 0.0
      this.vx = 0.0
      this.bloomIntensity = 0
      this.rotation = Math.random() * Math.PI * 2
      this.depth = Math.random() * 0.9 + 0.1
      this.velocity.x = Math.sign(Math.random() - 0.5) * this.depth * 0.25
      this.velocity.y = this.depth * 0.5 + 0.5
      this.velocity.rot = Math.random() * 2 - 1
    }
  }
}
